// Project Chatbot — keyword-based Q&A (no external API needed)
const body = $input.item.json.body || $input.item.json;
const query = (body.query || body.message || body.question || '').trim().toLowerCase();
const lang = (body.lang || 'fr').toLowerCase();

if (!query || query.length < 2) {
  return {
    status: 'ERROR',
    response: lang === 'fr'
      ? 'Veuillez poser une question (champ "query" requis).'
      : 'Please provide a question (field "query" required).',
    engine: 'PROJECT_CHATBOT',
    timestamp: new Date().toISOString()
  };
}

// Knowledge base — structured project information
const KB = {
  project: {
    fr: 'Nomos AI est un systeme d\'intelligence artificielle avance qui repond a des questions complexes en cherchant dans plusieurs bases de donnees simultanement. Il utilise 4 pipelines de recherche (Standard, Graph, Quantitatif, Orchestrateur) et un orchestrateur qui choisit la meilleure methode pour chaque question. Objectif final : traiter 1M+ questions dans 4 secteurs (BTP, Industrie, Finance, Juridique) avec 85%+ de precision.',
    en: 'Nomos AI is an advanced AI system that answers complex questions by searching multiple databases simultaneously. It uses 4 search pipelines (Standard, Graph, Quantitative, Orchestrator) that pick the best method for each question. Final target: process 1M+ questions across 4 sectors (Construction, Industry, Finance, Legal) with 85%+ accuracy.'
  },
  phase: {
    fr: 'Phase 1 (200 questions) : REUSSIE — 83.9% de precision globale (20 fev 2026). Phase 2 (1000q par pipeline) : EN COURS — Graph TERMINE (500/500, 78.0%), Quantitatif TERMINE (500/500, 92.0%), Standard EN PAUSE (579/1000, credits API epuises), Orchestrateur EN PAUSE (57/1000). Phase 3 (10,000q) : Prochaine etape. Phase 4 (100K) et Phase 5 (1M+) planifiees.',
    en: 'Phase 1 (200 questions): PASSED — 83.9% overall accuracy (20 Feb 2026). Phase 2 (1000q per pipeline): IN PROGRESS — Graph COMPLETE (500/500, 78.0%), Quantitative COMPLETE (500/500, 92.0%), Standard PAUSED (579/1000, API credits depleted), Orchestrator PAUSED (57/1000). Phase 3 (10,000q): Next. Phase 4 (100K) and Phase 5 (1M+) planned.'
  },
  pipelines: {
    fr: 'Les 4 pipelines RAG :\n1. Standard (recherche textuelle) : Question → generation HyDE → recherche vectorielle Pinecone (10,411 vecteurs) → reranking Jina → reponse LLM. Phase 1: 85.5%\n2. Graph (entites et relations) : Question → extraction entites → traversee Neo4j (19,788 noeuds, 76,717 relations) → synthese LLM. Phase 1: 78.0%\n3. Quantitatif (SQL/chiffres) : Question → analyse intention → generation SQL → requete Supabase → interpretation LLM. Phase 1: 92.0%\n4. Orchestrateur (combine les 3) : Question → classification intention → routage vers pipeline(s) → aggregation. Phase 1: 80.0%',
    en: 'The 4 RAG pipelines:\n1. Standard (text search): Question → HyDE generation → Pinecone vector search (10,411 vectors) → Jina reranking → LLM answer. Phase 1: 85.5%\n2. Graph (entity search): Question → entity extraction → Neo4j traversal (19,788 nodes, 76,717 relations) → LLM synthesis. Phase 1: 78.0%\n3. Quantitative (SQL/numbers): Question → intent analysis → SQL generation → Supabase query → LLM interpretation. Phase 1: 92.0%\n4. Orchestrator (combines all): Question → intent classification → route to best pipeline(s) → aggregate results. Phase 1: 80.0%'
  },
  infrastructure: {
    fr: 'Infrastructure : VM Google Cloud (pilotage), HuggingFace Space (n8n 16GB RAM, 14 workflows), GitHub Codespaces (tests lourds), 4 sites Vercel (production). Bases de donnees : Pinecone (10,411 vecteurs), Neo4j (19,788 noeuds), Supabase (65 tables). 7 repos GitHub prives.',
    en: 'Infrastructure: Google Cloud VM (control plane), HuggingFace Space (n8n 16GB RAM, 14 workflows), GitHub Codespaces (heavy testing), 4 Vercel websites (production). Databases: Pinecone (10,411 vectors), Neo4j (19,788 nodes), Supabase (65 tables). 7 private GitHub repos.'
  },
  capabilities: {
    fr: 'Capacites actuelles : Reponse a des questions factuelles (Standard), navigation dans un graphe de connaissances (Graph), requetes SQL automatiques sur donnees financieres (Quantitatif), routage intelligent (Orchestrateur). A venir : support multi-canal (WhatsApp, Telegram, Gmail, Slack), couverture 4 secteurs (BTP, Industrie, Finance, Juridique), ingestion sectorielle (7,600+ documents prets).',
    en: 'Current capabilities: Factual Q&A from text (Standard), knowledge graph navigation (Graph), auto-generated SQL on financial data (Quantitative), smart routing (Orchestrator). Coming: multi-channel support (WhatsApp, Telegram, Gmail, Slack), 4-sector coverage (Construction, Industry, Finance, Legal), sector data ingestion (7,600+ documents ready).'
  },
  accuracy: {
    fr: 'Precision Phase 1 (baseline 200q) : Standard 85.5%, Graph 78.0%, Quantitatif 92.0%, Orchestrateur 80.0%, Global 83.9%. Phase 2 (1000q) : Graph 78.0% (TERMINE), Quantitatif 92.0% (TERMINE), Standard ~36% (EN PAUSE), Orchestrateur 0% (EN PAUSE).',
    en: 'Phase 1 accuracy (200q baseline): Standard 85.5%, Graph 78.0%, Quantitative 92.0%, Orchestrator 80.0%, Overall 83.9%. Phase 2 (1000q): Graph 78.0% (COMPLETE), Quantitative 92.0% (COMPLETE), Standard ~36% (PAUSED), Orchestrator 0% (PAUSED).'
  },
  tech: {
    fr: 'Stack technique : LLMs gratuits via OpenRouter (Mistral Small, Trinity, StepFun Flash), embeddings Jina AI (1024 dimensions), Pinecone (base vectorielle), Neo4j Aura (graphe), Supabase PostgreSQL (SQL), n8n (moteur de workflows), Next.js sur Vercel (sites web), Claude Code Opus 4.6 (orchestration).',
    en: 'Tech stack: Free LLMs via OpenRouter (Mistral Small, Trinity, StepFun Flash), Jina AI embeddings (1024-dim), Pinecone (vector DB), Neo4j Aura (graph DB), Supabase PostgreSQL (SQL DB), n8n (workflow engine), Next.js on Vercel (websites), Claude Code Opus 4.6 (orchestration).'
  },
  next: {
    fr: 'Prochaines etapes : 1) Obtenir credits API Jina (debloque Standard + Graph). 2) Completer Phase 2 (Standard + Orchestrateur). 3) Phase 3 : 10,000 questions par pipeline. 4) Activer la passerelle PME multi-canal. 5) Ingestion donnees sectorielles. 6) Deploiement production 1M+ questions.',
    en: 'Next steps: 1) Get Jina API credits (unblocks Standard + Graph). 2) Complete Phase 2 (Standard + Orchestrator). 3) Phase 3: 10,000 questions per pipeline. 4) Activate PME multi-channel gateway. 5) Sector data ingestion. 6) Production deployment targeting 1M+ questions.'
  },
  sectors: {
    fr: 'Les 4 secteurs cibles : BTP/Construction (reglementations, DTU, normes), Industrie (maintenance, qualite, production), Finance (bilans, CA, analyse), Juridique (contrats, conformite, RGPD). 7,600+ documents sectoriels prets pour ingestion.',
    en: 'The 4 target sectors: Construction/BTP (regulations, standards), Industry (maintenance, quality, production), Finance (balance sheets, revenue, analysis), Legal (contracts, compliance, GDPR). 7,600+ sector documents ready for ingestion.'
  }
};

// Keyword matching
const topics = [
  { keys: ['nomos', 'what is', 'qu\'est', 'c\'est quoi', 'describe', 'decri', 'present'], topic: 'project' },
  { keys: ['phase', 'progress', 'avancement', 'etape', 'ou en', 'status', 'etat'], topic: 'phase' },
  { keys: ['pipeline', 'standard', 'graph', 'quantit', 'orchestr', 'rag'], topic: 'pipelines' },
  { keys: ['infra', 'server', 'machine', 'cloud', 'hf space', 'vercel', 'database', 'base de donn'], topic: 'infrastructure' },
  { keys: ['capab', 'capacit', 'peut faire', 'can do', 'feature', 'fonctionnalit'], topic: 'capabilities' },
  { keys: ['accura', 'precis', 'performance', 'score', 'result'], topic: 'accuracy' },
  { keys: ['tech', 'stack', 'outil', 'tool', 'llm', 'model', 'openrouter', 'pinecone', 'neo4j', 'supabase'], topic: 'tech' },
  { keys: ['next', 'prochain', 'futur', 'plan', 'coming', 'roadmap', 'suite'], topic: 'next' },
  { keys: ['sector', 'secteur', 'btp', 'industri', 'financ', 'juridique', 'legal', 'construction'], topic: 'sectors' }
];

let matchedTopic = null;
let maxMatches = 0;
for (const t of topics) {
  const matches = t.keys.filter(k => query.includes(k)).length;
  if (matches > maxMatches) {
    maxMatches = matches;
    matchedTopic = t.topic;
  }
}

let response;
if (matchedTopic && KB[matchedTopic]) {
  response = KB[matchedTopic][lang] || KB[matchedTopic]['en'];
} else {
  // Default: give overview
  response = KB.project[lang] || KB.project['en'];
  response += '\n\n' + (lang === 'fr'
    ? 'Pour plus de details, posez une question sur : les pipelines, la phase actuelle, l\'infrastructure, les capacites, la precision, la technologie, les prochaines etapes, ou les secteurs.'
    : 'For more details, ask about: pipelines, current phase, infrastructure, capabilities, accuracy, technology, next steps, or sectors.');
}

return {
  status: 'SUCCESS',
  response,
  query: body.query || body.message || body.question || '',
  topic: matchedTopic || 'overview',
  lang,
  engine: 'PROJECT_CHATBOT',
  timestamp: new Date().toISOString()
};

